import {Platform, TouchableOpacity, View} from 'react-native';
import TextCM from '../../../../components/Text';
import {Color, Font, NavigationName} from '../../../../../constants';
import Svg, {Ellipse, Line} from 'react-native-svg';
import {useEffect, useRef, useState} from 'react';
import {DateUtils} from '../../../../../utils';
import {
  listRequestStatus,
  listRequestStatusQDTHA,
  listSourceOfReceipt,
} from '../modal-filter/helper';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {useNavigation} from '@react-navigation/native';
import {RequestData} from '../../../../../model/interface/qdtha.interface';
import {useConfigStore} from '../../../zustand/config';
import {useQDTHAService} from '../../../../../hooks/apiHooks/useAPI';
type Props = {
  dycItem: RequestData;
  getDataDYC: (page: number, isLoadMore?: boolean) => void;
  setPage: (page: number) => void;
};

const DYCItem = ({dycItem, getDataDYC, setPage}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const {LIST_APPLICATION_STATUS} = useConfigStore();
  const [widthOfCard, setWidthOfCard] = useState(0);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const QDTHAService = useQDTHAService();

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const navigateToDetailReceiptScreen = (id: string) => {
    navigation.navigate(NavigationName.DetailDYCScreen, {id});
  };

  const handleGenerateNumber = async () => {
    const res = await QDTHAService.generateNewNumber(dycItem.id);
    if (res) {
      setPage(0);
      getDataDYC(0, false);
    }
  };

  const DashLine = () => {
    return (
      <Svg height="10" width={'100%'} style={styles.dashLine}>
        <Ellipse cx="0" cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Ellipse cx={'100%'} cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Line
          x1="20"
          y1="5"
          x2={widthOfCard - 20}
          y2="5"
          stroke="#cbcbcb"
          strokeWidth="1"
          strokeDasharray="8.8"
        />
      </Svg>
    );
  };

  const StatusTag = ({
    status,
    type,
  }: {
    status: string;
    type: 'DEFAULT' | 'REQUEST' | 'MIX';
  }) => {
    let properties;
    if (type === 'DEFAULT') {
      properties = listRequestStatusQDTHA.find(
        (item: any) => item.value === status,
      );
    } else if (type === 'REQUEST') {
      properties = LIST_APPLICATION_STATUS.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    } else {
      properties = listRequestStatus.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    }
    if (properties) {
      return (
        <View style={{flex: 1, flexDirection: 'row'}}>
          <View style={{flex: 1}} />
          <View
            style={[
              styles.statusTag,
              {backgroundColor: properties?.bgColor || '#EF5DA81A'},
            ]}>
            <TextCM
              style={[
                styles.statusText,
                {color: properties?.color || '#d94936'},
              ]}>
              {type == 'REQUEST'
                ? properties?.label
                : t(`BLDT.${properties?.value}`)}
            </TextCM>
          </View>
        </View>
      );
    }
    return (
      <View style={{flexDirection: 'row', flex: 1}}>
        <View style={{flex: 1}} />
        <View style={[styles.statusTag, {backgroundColor: '#EF5DA81A'}]}>
          <TextCM style={[styles.statusText, {color: '#d94936'}]}>
            {t(`BLDT.${status}`)}
          </TextCM>
        </View>
      </View>
    );
  };

  return (
    <TouchableOpacity
      onPress={() => navigateToDetailReceiptScreen(dycItem.id)}
      activeOpacity={Platform.OS === 'ios' ? 0.8 : 0.9}
      style={styles.container}>
      <View
        onLayout={event => {
          const {width} = event.nativeEvent.layout;
          setWidthOfCard(width);
        }}
        style={[
          styles.card,
          styles.radiusTop,
          styles.shadowTop,
          styles.shadowLeft,
          styles.shadowRight,
        ]}>
        <View style={styles.header}>
          <View style={{flex: 1, columnGap: 8}}>
            <TextCM style={styles.title}>{dycItem?.name || '---'}</TextCM>
            <TextCM style={styles.idNumber}>
              {dycItem.requestCode || '---'}
            </TextCM>
          </View>
          {dycItem.requestStatus === 'status_error_receipt' && (
            <TouchableOpacity
              onPress={() => handleGenerateNumber()}
              style={styles.capSoStyle}>
              <TextCM
                style={{color: Color.White, fontFamily: Font.InterMedium500}}>
                {t('BLDT.arithmetic')}
              </TextCM>
            </TouchableOpacity>
          )}
        </View>
      </View>

      <DashLine />

      <View
        style={[
          styles.card,
          styles.radiusBot,
          styles.shadowBottom,
          styles.shadowLeft,
          styles.shadowRight,
        ]}>
        <View style={styles.receiptTypeSection}>
          <View style={styles.lableCardWrap}>
            <TextCM style={styles.receiptTypeLabel}>{'Nguồn nhận'}</TextCM>
          </View>
          <View style={{flex: 1}}>
            <TextCM style={styles.receiptTypeCode}>
              {listSourceOfReceipt.find(item => item.value === dycItem?.type)
                ?.label ||
                dycItem?.type ||
                '---'}
            </TextCM>
          </View>
        </View>
        <View style={styles.receiptTypeSection}>
          <View style={styles.lableCardWrap}>
            <TextCM style={styles.receiptTypeLabel}>Người tạo</TextCM>
          </View>
          <View style={{flex: 1}}>
            <TextCM style={styles.receiptTypeCode}>
              {dycItem.createdBy || '---'}
            </TextCM>
          </View>
        </View>

        <View style={styles.dateSection}>
          <View style={styles.lableCardWrap}>
            <TextCM style={styles.dateLabel}>Ngày yêu cầu</TextCM>
          </View>
          <TextCM style={styles.dateValue}>
            {DateUtils.convertDateToDDMMYYYY_H_M(dycItem.createdDate) || '---'}
          </TextCM>
        </View>

        <View style={styles.statusSection}>
          <View style={styles.lableCardWrap}>
            <TextCM style={styles.statusLabel}>{'Trạng thái yêu cầu'}</TextCM>
          </View>
          {dycItem.requestStatus && (
            <StatusTag status={dycItem?.requestStatus} type={'REQUEST'} />
          )}
        </View>
        <View style={styles.statusSection}>
          <View style={styles.lableCardWrap}>
            <TextCM style={styles.statusLabel}>{'Trạng thái quy trình'}</TextCM>
          </View>
          {dycItem.flowStatus && (
            <StatusTag status={dycItem.flowStatus} type={'DEFAULT'} />
          )}
        </View>
      </View>
    </TouchableOpacity>
  );
};

export default DYCItem;
