import {create} from 'zustand';
import {IOrigin} from '../../../model/interface/orgin.interface';

interface ConfigState {
  LIST_APPLICATION_STATUS: any;
  LIST_ORG: any[];
  setListAPPLICATION_STATUS: (listAPPLICATION_STATUS: any) => void;
  setListOrg: (listOrg: any[]) => void;
}

const initialConfigState = {
  LIST_APPLICATION_STATUS: [],
  LIST_ORG: [],
};

export const useConfigStore = create<ConfigState>((set, get) => ({
  ...initialConfigState,
  setListAPPLICATION_STATUS: (listAPPLICATION_STATUS: any) => {
    set({LIST_APPLICATION_STATUS: listAPPLICATION_STATUS});
  },
  setListOrg: (listOrg: any[]) => {
    set({LIST_ORG: listOrg});
  },
}));
